correct_example.code:
function createVault(address token, uint256 amount) external {
    require(token.code.length > 0, "TOKEN_NOT_CONTRACT");
    SafeTransferLib.safeTransferFrom(token, msg.sender, address(this), amount);
    vaults[msg.sender].balance += amount;
    emit VaultCreated(msg.sender, token, amount);
}
